EURO = Decimal("55.2325")          # ECB 13.10.2026; sistemde kur tablosu yok, fiyatlar TL saklanır
STANDARD_EURO = {"Kış": 80, "Geçiş": 90, "Yaz": 100}
OTHER_EURO = {"Kış": 120, "Geçiş": 125, "Yaz": 130}


def seed_pricing(apps, schema_editor):
    RoomType = apps.get_model("dashboard", "RoomType")
    Season = apps.get_model("dashboard", "Season")
    BaseRate = apps.get_model("dashboard", "BaseRate")
    Event = apps.get_model("dashboard", "Event")
    # Hedef marj: en düşük katsayılı (standart) oda %50, kalite arttıkça her tipte +%5.
    for step, room_type in enumerate(RoomType.objects.order_by("standard_cost_factor", "code")):
        room_type.target_markup = Decimal("0.50") + Decimal("0.05") * step
        room_type.save(update_fields=["target_markup"])
    seasons = list(Season.objects.all())
    for step, room_type in enumerate(RoomType.objects.filter(active=True).order_by("standard_cost_factor", "code")):
        table = STANDARD_EURO if step == 0 else OTHER_EURO
        for season in seasons:
            if season.name not in table:
                continue
            euro = table[season.name]
            BaseRate.objects.get_or_create(room_type=room_type, season=season, defaults={
                "price": (EURO * euro).quantize(Decimal("0.01")),
                "notes": f"Varsayım: sitedeki fiyat aralığından {euro} € × {EURO} TL (ECB 13.10.2026).",
            })
    for name, kind, start, end, index, estimated, source, notes in EVENTS:
        Event.objects.get_or_create(name=name, start_date=start, defaults={
            "kind": kind, "end_date": end, "index": Decimal(index), "estimated": estimated,
            "source": source, "notes": notes})


